-- =============================================================================
-- THE ARQAM SCHOOLS: SIMPLER NAVIGATION AND FOUR MAIN PAGES (24 October 2026)
-- Run after 01-03 (fresh install) or on the live database. Safe to run twice:
-- it records itself in dbo.schema_migrations and stops if already applied.
--
-- What it does:
--  1. Backs up every row it changes into the [archive] schema (*_20261024 tables).
--  2. About, Academics, Admissions and Campuses become single pages: their header
--     dropdowns are removed and the subpages' content is merged into them.
--  3. The six old subpages are archived (kept, not deleted) and 301-redirected.
--  4. "Branches" becomes "Campuses" (/branches -> /campuses) in menus, links and text.
--  5. Network figures are updated to 350+ campuses, 250,000+ students and
--     20,000+ Hifz-e-Quran students.
-- Nothing is deleted except the dropdown menu entries, which are kept in the backup.
-- =============================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO
IF OBJECT_ID(N'dbo.schema_migrations') IS NULL
    CREATE TABLE dbo.schema_migrations (
        [id] NVARCHAR(100) NOT NULL CONSTRAINT PK_schema_migrations PRIMARY KEY,
        [applied_at] DATETIMEOFFSET(3) NOT NULL CONSTRAINT DF_schema_migrations_applied_at DEFAULT SYSDATETIMEOFFSET());
GO
IF SCHEMA_ID(N'archive') IS NULL EXEC(N'CREATE SCHEMA [archive]');
GO
IF EXISTS (SELECT 1 FROM dbo.schema_migrations WHERE id = N'04_simplify_navigation')
BEGIN
    PRINT N'04_simplify_navigation is already applied. Nothing to do.';
    SET NOEXEC ON;
END
GO
BEGIN TRANSACTION;

-- 1. Backups -------------------------------------------------------------------
SELECT * INTO archive.pages_20261024 FROM dbo.pages;
SELECT * INTO archive.page_sections_20261024 FROM dbo.page_sections;
SELECT * INTO archive.navigation_items_20261024 FROM dbo.navigation_items;
SELECT * INTO archive.site_settings_20261024 FROM dbo.site_settings;
SELECT * INTO archive.seo_metadata_20261024 FROM dbo.seo_metadata;
SELECT * INTO archive.homepage_content_20261024 FROM dbo.homepage_content;
SELECT * INTO archive.redirects_20261024 FROM dbo.redirects;

-- 2. Header menu: no dropdowns for About, Academics, Admissions and Campuses ----
DECLARE @header UNIQUEIDENTIFIER = (SELECT id FROM dbo.navigation_menus WHERE [key] = N'header');
DELETE c FROM dbo.navigation_items c
JOIN dbo.navigation_items p ON p.id = c.parent_id
WHERE p.menu_id = @header AND p.parent_id IS NULL AND p.url IN (N'/about', N'/academics', N'/admissions', N'/branches');

UPDATE dbo.navigation_items SET label = N'About Us', description = NULL, updated_at = SYSDATETIMEOFFSET()
WHERE menu_id = @header AND parent_id IS NULL AND url = N'/about';
UPDATE dbo.navigation_items SET description = NULL, updated_at = SYSDATETIMEOFFSET()
WHERE menu_id = @header AND parent_id IS NULL AND url IN (N'/academics', N'/admissions');
UPDATE dbo.navigation_items SET label = N'Campuses', url = N'/campuses', description = NULL, updated_at = SYSDATETIMEOFFSET()
WHERE menu_id = @header AND parent_id IS NULL AND url = N'/branches';

-- 3. Links and wording in all content ------------------------------------------
UPDATE dbo.page_sections SET data = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(data, N'/contact?type=admissions', N'/admissions#inquiry'), N'/about/vision-mission', N'/about#vision-mission'), N'/about/philosophy', N'/about#philosophy'), N'/about/values', N'/about#values'), N'/about/why-choose-us', N'/about#why-choose-us'), N'/academics/levels', N'/academics#levels'), N'/academics/teaching', N'/academics#teaching'), N'"/branches', N'"/campuses'), N'more than 300 branches', N'more than 350 campuses'), N'More than 300 branches', N'More than 350 campuses'), N'300+ branches', N'350+ campuses'), N'more than 300 schools', N'more than 350 campuses'), N'300+ schools', N'350+ campuses'), N'Branches across Pakistan', N'Campuses across Pakistan'), N'"300+"', N'"350+"'), N'over 200,000', N'over 250,000'), N'200,000+', N'250,000+'), N'more than 200,000', N'more than 250,000'), N'15,000', N'20,000'), N'Find a branch page', N'Campuses page'), N'Use Find a branch to choose', N'Use the Campuses page to choose'), N'Find a branch', N'Find a campus'), N'Find a Branch', N'Find a Campus'), N'Find an Arqam school near you', N'Find a campus of The Arqam Schools near you'), draft_data = CASE WHEN draft_data IS NULL THEN NULL ELSE REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(draft_data, N'/contact?type=admissions', N'/admissions#inquiry'), N'/about/vision-mission', N'/about#vision-mission'), N'/about/philosophy', N'/about#philosophy'), N'/about/values', N'/about#values'), N'/about/why-choose-us', N'/about#why-choose-us'), N'/academics/levels', N'/academics#levels'), N'/academics/teaching', N'/academics#teaching'), N'"/branches', N'"/campuses'), N'more than 300 branches', N'more than 350 campuses'), N'M