-- 4. The four main pages -------------------------------------------------------
-- about
DECLARE @p_about UNIQUEIDENTIFIER = (SELECT id FROM dbo.pages WHERE slug = N'about' AND parent_id IS NULL);
UPDATE dbo.pages SET title = N'About us', summary = N'Who we are, what we believe and why families choose The Arqam Schools.', status = N'published', updated_at = SYSDATETIMEOFFSET() WHERE id = @p_about;
DELETE FROM dbo.page_sections WHERE page_id = @p_about;
INSERT INTO dbo.page_sections (page_id, [type], data, sort_order, is_visible) VALUES
  (@p_about, N'split_feature', N'{"anchor":"who-we-are","eyebrow":"About The Arqam Schools","heading":"One network, one purpose","image_side":"right","body":["The Arqam Schools is an educational network in Pakistan with 350+ campuses and more than 250,000 students. Classes run from Play Group to Matric, and more than 20,000 students are memorising the Holy Quran in our Hifz classes.","We combine modern academic education with Islamic education, ethics and discipline, so that every child grows in knowledge, character and confidence."],"image":{"bucket":"public-media","path":"network/content/about-campus--20261014075037.jpg","alt":"Students of different ages walking together outside a school building","width":800,"height":600}}', 1, 1),
  (@p_about, N'vision_mission', N'{"anchor":"vision-mission","heading":"Our vision and mission","tone":"warm","vision":{"title":"Our vision","body":"To raise a generation who combine knowledge with values: confident, capable and caring young Muslims who lead with good character, serve their families, their communities and Pakistan, and succeed in this world and the Hereafter."},"mission":{"title":"Our mission","intro":"Every campus of The Arqam Schools works to:","points":["Provide quality modern education that builds understanding and good study habits","Teach the Holy Quran and Islamic studies, and encourage good conduct","Develop discipline, honesty, good manners and responsibility","Give children chances to speak, create, take part and lead","Keep a close partnership between home and school"]}}', 2, 1),
  (@p_about, N'split_feature', N'{"anchor":"philosophy","eyebrow":"Educational philosophy","heading":"Educating the whole child","image_side":"left","body":["Education is more than passing examinations. We develop a child''s mind, faith and character together, in calm and orderly classrooms where children feel safe, respected and encouraged to ask questions.","Clear routines, attention to every child''s progress and a close partnership with parents help children learn steadily and behave well."],"image":{"bucket":"public-media","path":"network/content/teacher-with-students--20261014075037.jpg","alt":"A teacher patiently guiding a young student during a Quran lesson","width":1183,"height":887}}', 3, 1),
  (@p_about, N'card_grid', N'{"anchor":"why-choose-us","heading":"Why choose The Arqam Schools?","tone":"grey","columns":4,"items":[{"icon":"book-open","title":"Knowledge with values","summary":"Modern academic education and Islamic education, taught together."},{"icon":"sparkles","title":"The whole child","summary":"Character, discipline, confidence and creativity matter as much as marks."},{"icon":"graduation-cap","title":"Play Group to Matric","summary":"One school family for the whole school journey, with Hifz classes."},{"icon":"heart-handshake","title":"Partnership with parents","summary":"Regular communication and shared expectations between home and school."}]}', 4, 1),
  (@p_about, N'values', N'{"anchor":"values","heading":"Islamic values and character building","tone":"white","body":"Islamic education is part of everyday school life. Students learn to read and recite the Holy Quran, study Islamic teachings suited to their age, and practise good character at school and at home.","items":[{"icon":"moon-star","title":"Faith and worship","description":"The Holy Quran, duas and the basics of worship, taught with respect and love."},{"icon":"shield-check","title":"Honesty","description":"Telling the truth, keeping promises and doing one''s own work."},{"icon":"users","title":"Respect and good manners","description":"Greeting with salaam, speaking kindly and respecting parents, teachers and classmates."},{"icon":"compass","title":"Discipline and responsibility","description":"Punctuality, neatness, self-control and caring for others."}],"quote":{"text":"The basic aim and idea of The Arqam Schools is to earn the pleasure of Allah through the acts of education.","source":"The Arqam Schools"}}', 5, 1),
  (@p_about, N'cta_band', N'{"tone":"warm","heading":"See The Arqam Schools for yourself","body":"Find a campus near you and arrange a visit.","primary_cta":{"href":"/campuses","label":"Find a campus"},"secondary_cta":{"href":"/contact","label":"Contact us"}}', 6, 1);
IF EXISTS (SELECT 1 FROM dbo.pages WHERE id = @p_about AND seo_id IS NOT NULL)
    UPDATE s SET meta_title = N'About Us | The Arqam Schools', meta_description = N'The Arqam Schools: 350+ campuses across Pakistan combining modern education with Islamic values, discipline and character building, from Play Group to Matric.', og_title = NULL, og_description = NULL, canonical_url = NULL, robots_noindex = 0, updated_at = SYSDATETIMEOFFSET()
    FROM dbo.seo_metadata s JOIN dbo.pages pg ON pg.seo_id = s.id WHERE pg.id = @p_about;
ELSE
BEGIN
    DECLARE @seo_about TABLE (id UNIQUEIDENTIFIER);
    INSERT INTO dbo.seo_metadata (meta_title, meta_description) OUTPUT inserted.id INTO @seo_about VALUES (N'About Us | The Arqam Schools', N'The Arqam Schools: 350+ campuses across Pakistan combining modern education with Islamic values, discipline and character building, from Play Group to Matric.');
    UPDATE dbo.pages SET seo_id = (SELECT id FROM @seo_about) WHERE id = @p_about;
END
-- academics
DECLARE @p_academics UNIQUEIDENTIFIER = (SELECT id FROM dbo.pages WHERE slug = N'academics' AND parent_id IS NULL);
UPDATE dbo.pages SET title = N'Academics', summary = N'Strong teaching from Play Group to Matric, with Hifz classes, building knowledge, skills and good character together.', status = N'published', updated_at = SYSDATETIMEOFFSET() WHERE id = @p_academics;
DELETE FROM dbo.page_sections WHERE page_id = @p_academics;
INSERT INTO dbo.page_sections (page_id, [type], data, sort_order, is_visible) VALUES
  (@p_academics, N'split_feature', N'{"anchor":"excellence","eyebrow":"Academic excellence","heading":"High expectations, steady progress","image_side":"right","body":["Children build strong foundations in reading, writing, mathematics, science and computer skills step by step, alongside the Holy Quran and Islamic studies.","Teachers plan lessons carefully, check understanding regularly and keep parents informed, so that support at home matches learning at school."],"image":{"bucket":"public-media","path":"network/content/students-reading-together--20261014075037.jpg","alt":"Two primary students reading together at a desk with their schoolbooks","width":585,"height":439}}', 1, 1),
  (@p_academics, N'card_grid', N'{"anchor":"teaching","heading":"Teaching methodology","tone":"grey","columns":4,"intro":"Lessons follow a simple rhythm that children come to know and trust: explain clearly, practise regularly, check understanding and give feedback.","items":[{"title":"Clear explanation","summary":"New ideas are introduced step by step, in calm and orderly classrooms.","image":{"bucket":"public-media","path":"network/content/girl-writing-in-class--20261014075037.jpg","alt":"A girl writing carefully in her exercise book in class","width":427,"height":320}},{"title":"Active, hands-on learning","summary":"Discussion, group work, activities and projects bring lessons to life.","image":{"bucket":"public-media","path":"network/content/hands-on-building-activity--20261014075037.jpg","alt":"Two children building a toy car together in a hands-on activity","width":427,"height":320}},{"title":"Practice and feedback","summary":"Classwork and homework help children remember; feedback shows them how to improve.","image":{"bucket":"public-media","path":"network/content/library-reading--20261014075037.jpg","alt":"A boy reading a picture book in front of a bookshelf","width":427,"height":320}},{"title":"Values in every lesson","summary":"Teachers model honesty, respect and good manners as they teach.","image":{"bucket":"public-media","path":"network/content/boy-thumbs-up-values--20261014075037.jpg","alt":"A smiling boy giving a thumbs up in front of a classroom values board","width":427,"height":320}}]}', 2, 1),
  (@p_academics, N'academic_levels', N'{"anchor":"levels","heading":"Academic levels","tone":"white","intro":"Classes run from Play Group to Matric, with Hifz classes. Classes can vary by campus, so please check with your nearest campus.","items":[{"stage":"Early Years","title":"Early Years","summary":"A happy, caring start through play, stories, routines and first duas.","image":{"bucket":"public-media","path":"network/content/level-early-years--20261014075037.jpg","alt":"Young children building with colourful blocks in an early years classroom","width":1365,"height":1024}},{"stage":"Primary","title":"Primary","summary":"Fluent reading, clear writing, confident arithmetic and early science.","image":{"bucket":"public-media","path":"network/content/level-primary--20261014075037.jpg","alt":"Primary pupils at their desks, a girl raising her hand to answer","width":1255,"height":941}},{"stage":"Middle","title":"Middle","summary":"Deeper learning in each subject and growing independence.","image":{"bucket":"public-media","path":"network/content/level-middle--20261014075037.jpg","alt":"Students using a microscope and test tubes in a science lesson with their teacher","width":1365,"height":1024}},{"stage":"Matric","title":"Matric","summary":"Focused preparation for the Matric examinations and the next step.","image":{"bucket":"public-media","path":"network/content/level-secondary--20261014075037.jpg","alt":"Two secondary students studying together with their textbooks","width":1183,"height":887}},{"stage":"Hifz","title":"Hifz-e-Quran","summary":"Memorising the Holy Quran with correct recitation, guided by teachers.","image":{"bucket":"public-media","path":"network/content/hifz-quran-class--20261014075037.jpg","alt":"A boy in a Hifz class reciting from the Holy Quran on a rehal as his teacher guides him","width":1183,"height":887}}]}', 3, 1),
  (@p_academics, N'values', N'{"anchor":"development","heading":"Student development","tone":"warm","body":"We help every child grow in four connected ways.","items":[{"icon":"book-open","title":"Academic","description":"Knowledge, skills and good study habits in every subject."},{"icon":"compass","title":"Intellectual","description":"Asking questions, explaining their thinking and solving problems."},{"icon":"moon-star","title":"Ethical","description":"Islamic values, honesty, respect and responsibility."},{"icon":"users","title":"Personal","description":"Confidence in speaking, presenting, teamwork and leadership."}]}', 4, 1),
  (@p_academics, N'cta_band', N'{"tone":"navy","heading":"Which classes does your nearest campus offer?","body":"Classes and availability vary by campus. Find a campus or send us an admission inquiry.","primary_cta":{"href":"/admissions#inquiry","label":"Send an admission inquiry"},"secondary_cta":{"href":"/campuses","label":"Find a campus"}}', 5, 1);
IF EXISTS (SELECT 1 FROM dbo.pages WHERE id = @p_academics AND seo_id IS NOT NULL)
    UPDATE s SET meta_title = N'Academics | The Arqam Schools', meta_description = N'Academics at The Arqam Schools: academic excellence, teaching methodology and classes from Play Group to Matric, with Hifz-e-Quran.', og_title = NULL, og_description = NULL, canonical_url = NULL, robots_noindex = 0, updated_at = SYSDATETIMEOFFSET()
    FROM dbo.seo_metadata s JOIN dbo.pages pg ON pg.seo_id = s.id WHERE pg.id = @p_academics;
ELSE
BEGIN
    DECLARE @seo_academics TABLE (id UNIQUEIDENTIFIER);
    INSERT INTO dbo.seo_metadata (meta_title, meta_description) OUTPUT inserted.id INTO @seo_academics VALUES (N'Academics | The Arqam Schools', N'Academics at The Arqam Schools: academic excellence, teaching methodology and classes from Play Group to Matric, with Hifz-e-Quran.');
    UPDATE dbo.pages SET seo_id = (SELECT id FROM @seo_academics) WHERE id = @p_academics;
END
-- admissions
DECLARE @p_admissions UNIQUEIDENTIFIER = (SELECT id FROM dbo.pages WHERE slug = N'admissions' AND parent_id IS NULL);
UPDATE dbo.pages SET title = N'Admissions', summary = N'How admission works at The Arqam Schools, the classes available and how to send an admission inquiry.', status = N'published', updated_at = SYSDATETIMEOFFSET() WHERE id = @p_admissions;
DELETE FROM dbo.page_sections WHERE page_id = @p_admissions;
INSERT INTO dbo.page_sections (page_id, [type], data, sort_order, is_visible) VALUES
  (@p_admissions, N'page_header', N'{"eyebrow":"Admissions","title":"Begin Your Child''s Journey With The Arqam Schools","intro":"Modern education rooted in Islamic values, from Play Group to Matric, with Hifz classes. Send us an inquiry and the campus team will guide you through admission.","primary_cta":{"href":"#inquiry","label":"Apply for Admission"},"secondary_cta":{"href":"/campuses","label":"Find a campus"},"image":{"bucket":"public-media","path":"network/content/admissions-banner--20261014075037.jpg","alt":"A teacher reading with a smiling student in the classroom","width":722,"height":406}}', 1, 1),
  (@p_admissions, N'card_grid', N'{"anchor":"why-choose-us","heading":"Why choose The Arqam Schools?","tone":"white","columns":4,"items":[{"icon":"book-open","title":"Knowledge with values","summary":"Quality academic teaching together with Islamic education."},{"icon":"shield-check","title":"Discipline and character","summary":"Good manners, honesty and responsibility in a caring environment."},{"icon":"graduation-cap","title":"Play Group to Matric","summary":"One school family for your child''s whole journey, with Hifz classes."},{"icon":"map-pin","title":"A campus near you","summary":"350+ campuses across Pakistan."}]}', 2, 1),
  (@p_admissions, N'process_steps', N'{"anchor":"process","heading":"Admission process","tone":"grey","intro":"Admission is arranged by each campus. These are the usual steps.","steps":[{"title":"Find a campus","description":"Use the Campuses page to choose a campus near your home."},{"title":"Get in touch","description":"Call the campus or send an admission inquiry using the form on this page."},{"title":"Visit and discuss","description":"Visit the campus, meet the team and ask about classes, availability and fees."},{"title":"Complete admission","description":"The campus will explain the documents and steps needed to complete admission."}]}', 3, 1),
  (@p_admissions, N'info_list', N'{"anchor":"requirements","heading":"Eligibility and requirements","tone":"white","intro":"Requirements are set by each campus for each class. When you contact the campus, they will confirm:","items":["Which class suits your child''s age and previous schooling","Whether an assessment or meeting is part of admission","The documents to bring when you visit","The current fee structure for the class"],"note":"Please contact the campus before your visit so that you can bring everything you need."}', 4, 1),
  (@p_admissions, N'academic_levels', N'{"anchor":"levels","heading":"Classes available","tone":"warm","compact":true,"intro":"Classes can vary by campus. Please check with the campus you are interested in.","link":{"href":"/academics#levels","label":"More about our academic levels"},"items":[{"stage":"Early Years","title":"Early Years"},{"stage":"Primary","title":"Primary"},{"stage":"Middle","title":"Middle"},{"stage":"Matric","title":"Matric"},{"stage":"Hifz","title":"Hifz-e-Quran"}]}', 5, 1),
  (@p_admissions, N'admission_inquiry', N'{"anchor":"inquiry","heading":"Admission inquiry","tone":"white","intro":"Tell us about your child and the campus you are interested in. The campus team will contact you to explain the next steps.","success":"Thank you. Your inquiry has been received and the campus team will contact you soon."}', 6, 1),
  (@p_admissions, N'faq', N'{"anchor":"faq","heading":"Frequently asked questions","tone":"grey","items":[{"question":"How do I apply for admission?","answer":"Find your nearest campus on the Campuses page, then call the campus or send an admission inquiry using the form on this page. The campus team will explain the available classes, the documents needed and the next steps."},{"question":"Which classes do you offer?","answer":"Our classes run from Play Group to Matric, and we also offer Hifz classes. Classes can vary by campus, so please check with the campus you are interested in."},{"question":"What are the fees?","answer":"Fees depend on the campus and the class. Please contact the campus directly for the current fee structure."},{"question":"Is there an admission test or interview?","answer":"Admission arrangements depend on the class and the campus. The campus will tell you whether an assessment or meeting is part of the process for your child."},{"question":"What documents will I need?","answer":"The campus will give you the list of documents for admission. Please contact the campus before your visit so that you can bring everything you need."}]}', 7, 1);
IF EXISTS (SELECT 1 FROM dbo.pages WHERE id = @p_admissions AND seo_id IS NOT NULL)
    UPDATE s SET meta_title = N'Admissions | The Arqam Schools', meta_description = N'Admissions at The Arqam Schools: the admission process, classes from Play Group to Matric and Hifz, frequently asked questions and an online admission inquiry.', og_title = NULL, og_description = NULL, canonical_url = NULL, robots_noindex = 0, updated_at = SYSDATETIMEOFFSET()
    FROM dbo.seo_metadata s JOIN dbo.pages pg ON pg.seo_id = s.id WHERE pg.id = @p_admissions;
ELSE
BEGIN
    DECLARE @seo_admissions TABLE (id UNIQUEIDENTIFIER);
    INSERT INTO dbo.seo_metadata (meta_title, meta_description) OUTPUT inserted.id INTO @seo_admissions VALUES (N'Admissions | The Arqam Schools', N'Admissions at The Arqam Schools: the admission process, classes from Play Group to Matric and Hifz, frequently asked questions and an online admission inquiry.');
    UPDATE dbo.pages SET seo_id = (SELECT id FROM @seo_admissions) WHERE id = @p_admissions;
END
-- branches
DECLARE @p_branches UNIQUEIDENTIFIER = (SELECT id FROM dbo.pages WHERE slug = N'branches' AND parent_id IS NULL);
UPDATE dbo.pages SET title = N'Campuses', summary = N'Find a campus of The Arqam Schools by name, city, district or area.', status = N'published', updated_at = SYSDATETIMEOFFSET(), slug = N'campuses', path = N'/campuses' WHERE id = @p_branches;
DELETE FROM dbo.page_sections WHERE page_id = @p_branches;
INSERT INTO dbo.page_sections (page_id, [type], data, sort_order, is_visible) VALUES
  (@p_branches, N'page_header', N'{"eyebrow":"Campuses","title":"Explore The Arqam Schools Campuses","intro":"The Arqam Schools has 350+ campuses across Pakistan. Search by campus name, city, district or area to find contact details, classes and directions."}', 1, 1),
  (@p_branches, N'campus_directory', N'{"anchor":"find","heading":"Find a campus","tone":"white","empty":"No campus matches your search. Try another city or area, or contact the head office and we will help you find the nearest campus.","note":"More campuses are being added to this directory. If you cannot find your campus, please contact the head office."}', 2, 1),
  (@p_branches, N'cta_band', N'{"anchor":"inquiry","tone":"warm","heading":"Need help finding a campus?","body":"Contact the head office or send an admission inquiry, and we will put you in touch with the right campus.","primary_cta":{"href":"/admissions#inquiry","label":"Send an admission inquiry"},"secondary_cta":{"href":"/contact","label":"Contact us"}}', 3, 1);
IF EXISTS (SELECT 1 FROM dbo.pages WHERE id = @p_branches AND seo_id IS NOT NULL)
    UPDATE s SET meta_title = N'Campuses | The Arqam Schools', meta_description = N'Find a campus of The Arqam Schools near you. Search 350+ campuses across Pakistan by name, city, district or area for contact details and directions.', og_title = NULL, og_description = NULL, canonical_url = NULL, robots_noindex = 0, updated_at = SYSDATETIMEOFFSET()
    FROM dbo.seo_metadata s JOIN dbo.pages pg ON pg.seo_id = s.id WHERE pg.id = @p_branches;
ELSE
BEGIN
    DECLARE @seo_branches TABLE (id UNIQUEIDENTIFIER);
    INSERT INTO dbo.seo_metadata (meta_title, meta_description) OUTPUT inserted.id INTO @seo_branches VALUES (N'Campuses | The Arqam Schools', N'Find a campus of The Arqam Schools near you. Search 350+ campuses across Pakistan by name, city, district or area for contact details and directions.');
    UPDATE dbo.pages SET seo_id = (SELECT id FROM @seo_branches) WHERE id = @p_branches;
END

